import {STORE_SHELVES,STORE_CATEGORIES,PRODUCT_DETAILS} from './store-data.js';
import {CATALOG,money,itemPrice,selection,deliveryWindow,windowLabel} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(f,a='',cls='')=>f?`<img src="/assets/${f}" alt="${esc(a)}" class="${cls}" loading="lazy" decoding="async">`:'';
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const simplePrice=n=>n%100===0?'$'+String(n/100):money(n);
let context;
let navTimer;
let openMenu='';
let mediaObserver;
const prefersReduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const clean=t=>String(t||'').replace(/\s*Footnote\s*[^\w\s]?/g,'').replace(/\s+- \(Opens in a new window\)/g,'').trim();

function cardRoute(c){return c.productId&&CATALOG.some(p=>p.id===c.productId)?'#product/'+c.productId:c.name.includes('accessories')||c.name.includes('favorites')?'#category/Accessories':'#info/'+encodeURIComponent(c.name);}
function storeCard(c){
  const href=cardRoute(c);
  if(c.type==='accessory')return `<article class="store-card accessory-card" style="--card-width:313px"><a href="${href}" class="store-card-link">${img(c.image,c.name,'accessory-photo')}<div class="accessory-colors">${c.swatches.slice(0,7).map(f=>img(f,'')).join('')}</div><div class="accessory-copy"><span class="accessory-new">${c.badge==='New'?'New':''}</span><h3>${esc(c.name)}</h3><p>${c.price?money(c.price):''}</p></div></a></article>`;
  const p=CATALOG.find(p=>p.id===c.productId);
  return `<article class="store-card ${c.dark?'store-card-dark':''} ${c.videoFile?'has-preview':''}" style="--card-width:${c.width>=450?'480':'400'}px"><a href="${href}" class="store-card-link">${c.image?img(c.image,'','store-card-photo'):''}${c.videoFile?`<video class="store-preview" muted playsinline preload="metadata" ${c.image?`poster="/assets/${c.image}"`:''} aria-label="${esc(c.name)} preview"><source src="/assets/${c.videoFile}" type="video/mp4"></video>`:''}<div class="store-card-copy"><span class="store-badge">${esc(c.badge)}</span><h3>${esc(c.name)}</h3>${c.description?`<p class="store-card-tagline">${esc(c.description)}</p>`:''}${c.price?`<p class="store-card-finance">${c.type==='editorial'&&c.monthly?'From ':''}${c.monthly?simplePrice(c.price):money(c.price)}${c.monthly?` or $${c.monthly}/mo. for ${c.months} mo.<sup>∆</sup>`:''}${c.lease?`<br>Lease from $${c.lease}/mo. for ${c.leaseMonths} mo. with Apple&nbsp;Upgrade<sup>§</sup>`:''}</p>`:''}</div></a>${c.videoFile?'<button class="preview-control" data-action="preview" aria-label="Replay product preview">↻</button>':''}</article>`;
}
export function renderCatalogCard(p){return storeCard({name:p.name,badge:p.badge,description:p.tag,price:p.price,monthly:PRODUCT_DETAILS[p.id]?.monthly,lease:PRODUCT_DETAILS[p.id]?.lease,months:p.category==='iPhone'?24:12,leaseMonths:36,productId:p.id,image:p.card||p.image,dark:p.dark,width:400,type:p.category==='Accessories'?'accessory':'editorial',swatches:[]});}
const benefits=[
 {icon:'return',text:'Trade in your current device. Get credit toward a new one.',color:'#007aff'},
 {icon:'truck',text:'Enjoy two-hour delivery from an Apple Store, free delivery, or easy pickup.',color:'#008009'},
 {icon:'wallet',text:'Pay in full, pay monthly, or lease and upgrade at the end of your term.',color:'#ff4f20'},
 {icon:'bag',text:'Get a personalized shopping experience in the Apple Store app.',color:'#007aff'},
 {icon:'sparkle',text:'Make them yours. Engrave a mix of emoji, names, and numbers for free.',color:'#ac39ff'},
 {icon:'box',text:'Customize a Mac and style an Apple Watch just for them.',color:'#007aff'}
];
function shelf(s,i,ctx){let content=s.cards.map(storeCard).join('');if(i===3){content=storeCard(s.cards[0])+[0,2,4].map(j=>`<div class="benefit-column">${benefits.slice(j,j+2).map(b=>`<a href="#info/${encodeURIComponent(b.text)}" class="store-card benefit-card" style="--benefit-color:${b.color}">${ctx.icon(b.icon)}<h3>${b.text}</h3></a>`).join('')}</div>`).join('');}return `<section class="apple-shelf" data-shelf="${i}" aria-label="${esc(s.title)}"><h2 class="apple-shelf-heading">${esc(s.title)} <span>${esc(s.subtitle)}</span></h2><div class="store-track" tabindex="0" aria-label="${esc(s.title)} product carousel">${content}</div><div class="shelf-controls"><button data-action="shelf-prev" aria-label="Previous - ${esc(s.title)}" disabled>${arrow}</button><button data-action="shelf-next" aria-label="Next - ${esc(s.title)}">${arrow}</button></div></section>`;}
export function renderStore(category,ctx){
  const products=CATALOG.filter(p=>p.category===category||(category==='AirTag'&&p.id==='airtag')||(category==='Apple Gift Card'&&p.id==='gift-card'));
  return `<div class="apple-ribbon">Lease a new Apple product with low monthly payments and terms that work for you with Apple Upgrade.<sup>◊</sup> <a href="#info/Apple%20Upgrade">Learn more ›</a></div><div class="store-masthead"><h1>${category?esc(category==='Watch'?'Apple Watch':category):'Store'}</h1><div class="store-masthead-right"><h2>${category?'Find the one that’s right for you.':'The best way to buy the<br>products you love.'}</h2><button data-action="shopping-guide">Connect with a Specialist ↗</button><button data-action="store-location">Find an Apple Store ↗</button></div></div><nav class="apple-product-nav" aria-label="Product">${STORE_CATEGORIES.map(c=>`<a href="#category/${encodeURIComponent(c.name)}" class="apple-product-category ${c.name===category?'active':''}">${img(c.image,'')}<span>${c.label}</span></a>`).join('')}</nav>${category?`<section class="apple-shelf category-lineup"><h2 class="apple-shelf-heading">All models. <span>Take your pick.</span></h2><div class="category-products">${products.length?products.map(p=>storeCard({name:p.name,badge:p.badge,description:p.tag,price:p.price,monthly:PRODUCT_DETAILS[p.id]?.monthly,lease:PRODUCT_DETAILS[p.id]?.lease,months:['iPhone'].includes(p.category)?24:12,leaseMonths:36,productId:p.id,image:p.card||p.image,dark:p.dark,width:400,type:p.category==='Accessories'?'accessory':'editorial',swatches:[]})).join(''):`<div class="empty-category"><p>Explore your next favorite accessory.</p><a href="#category/Accessories">Shop accessories ›</a></div>`}</div></section>`:STORE_SHELVES.map((s,i)=>shelf(s,i,ctx)).join('')}<section class="apple-quicklinks"><h2>Quick Links</h2><a href="#info/Find%20a%20Store">Find a Store</a><a href="#orders">Order Status</a><a href="#info/Shopping%20Help">Shopping Help</a><a href="#info/Returns">Returns</a><a href="#saved">Your Saves</a></section><button class="specialist-bubble" data-action="shopping-guide" aria-label="Connect with a Specialist"><img src="/assets/specialist-avatar.png" alt=""></button>`;
}

function configGroup(g,ctx){const value=ctx.draft.choices?.[g.id]??0;return `<fieldset class="replica-group"><legend>${esc(g.title)} <span>${esc(g.subtitle)}</span></legend>${g.options.map((o,i)=>`<button class="apple-choice ${value===i?'selected':''}" data-action="extra" data-key="${esc(g.id)}" data-index="${i}" aria-pressed="${value===i}"><span><strong>${esc(o.label)}</strong>${o.detail?`<small>${esc(o.detail)}</small>`:''}</span><span>${o.add?`${o.add>0?'+':'−'} ${money(Math.abs(o.add))}`:'Included'}</span></button>`).join('')}</fieldset>`;}
function helpTile(title,desc,topic){return `<button class="config-help-tile" data-action="product-help" data-topic="${esc(topic||title)}"><span><strong>${esc(title)}</strong>${desc?`<small>${esc(desc)}</small>`:''}</span><span class="circle-plus">+</span></button>`;}
export function renderProduct(id,ctx){
  const p=CATALOG.find(p=>p.id===id);if(!p)return '<div class="empty-state"><h1>Find your next favorite.</h1><a href="#store">Back to the Store ›</a></div>';
  const d=ctx.draft;const item={...selection(id,d.color,d.option,d.care),choices:d.choices||{}};const price=itemPrice(item);
  const meta=PRODUCT_DETAILS[id];const accessory=['Accessories','AirTag','Apple Gift Card'].includes(p.category);const compact=accessory||['AirPods','Home'].includes(p.category);
  let gallery=p.gallery?.length?p.gallery:meta?.gallery?.length?meta.gallery:[p.image];
  if(d.galleryColor===d.color&&p.colorGalleries?.[p.colors[d.color].name])gallery=p.colorGalleries[p.colors[d.color].name];
  else if(d.galleryColor===d.color&&p.colors[d.color].image)gallery=[p.colors[d.color].image,...gallery.filter(x=>x!==p.colors[d.color].image)];
  const slide=Math.min(d.gallery||0,gallery.length-1);const delivery=deliveryWindow([item],'standard',ctx.now());
  const groups=p.groups||[];const layoutGroups=groups.filter(g=>g.id!=='trade-in');
  const mac=p.category==='Mac';
  const colorField=p.colors.length>1?`<fieldset class="replica-group finish-group"><legend>${mac?'Color.':'Finish.'} <span>Pick your favorite.</span></legend><p class="selected-color">Color - ${esc(p.colors[d.color].name)}</p><div class="swatches">${p.colors.map((c,i)=>`<button class="swatch ${i===d.color?'active':''}" data-action="color" data-index="${i}" style="--swatch:${c.hex}" aria-label="${esc(c.name)}" aria-pressed="${i===d.color}"><span></span></button>`).join('')}</div></fieldset>`:'';
  const storage=`<fieldset class="replica-group"><legend>${p.optionName}. <span>${p.optionName==='Storage'?'How much space do you need?':p.optionName==='Amount'?'How much would you like?':'Choose the one that works for you.'}</span></legend>${p.options.map((o,i)=>`<button class="apple-choice storage-choice ${d.option===i?'selected':''}" data-action="option" data-index="${i}" aria-pressed="${d.option===i}"><strong>${esc(o[0])}${p.optionName==='Storage'?'<sup>1</sup>':''}</strong>${p.category==='Apple Gift Card'?'':`<span>Buy from ${simplePrice(p.price+o[1])}<br>or ${meta?.optionDetails?.[i]?.monthly?'$'+meta.optionDetails[i].monthly:money(Math.floor((p.price+o[1])/(p.category==='iPhone'?24:12)))}/mo. for ${p.category==='iPhone'?24:12} mo.<sup>※</sup>${p.category==='iPhone'?`<br>Lease from ${meta?.optionDetails?.[i]?.lease?'$'+meta.optionDetails[i].lease:money(Math.ceil((p.price+o[1])*.029))}/mo. for 24 mo.<sup>#</sup>`:''}</span>`}</button>`).join('')}</fieldset>`;

  return `${p.category==='iPhone'?`<div class="carrier-ribbon"><strong>Carrier Deals at Apple<br><button data-action="product-help" data-topic="Carrier deals">See all deals ⊕</button></strong><span><b class="carrier-att">◉</b> Save up to $1200 after trade-in.<sup>∆</sup></span><span><b class="carrier-tmobile">T</b> Save up to $1000 with an eligible trade-in.<sup>§</sup></span><span><b class="carrier-verizon">V</b> Save up to $840 with an eligible trade-in.<sup>±</sup></span></div>`:''}<div class="apple-buy-page ${compact?'accessory-buy-page':''}"><header class="apple-buy-heading"><div><span class="new-label">${p.badge==='EXPLORE'?'':p.badge?'New':''}</span><h1>${accessory?'':compact?'Buy ':'Shop '}${p.name}</h1><p>${money(price)}</p>${['iPhone','iPad','Mac'].includes(p.category)?'<div class="intelligence-caption">✺ Apple Intelligence and Siri AI<sup>4</sup> <button data-action="product-help" data-topic="Apple Intelligence">Learn more ⊕</button></div>':''}</div><div class="buy-heading-links"><button data-action="product-help" data-topic="Apple Trade In">Get credit for your trade-in. ⊕</button><button data-action="product-help" data-topic="Payment options">See how to pay monthly. ⊕</button></div></header><div class="apple-buy-layout"><div class="apple-gallery"><div class="apple-gallery-stage ${accessory?'accessory-stage':''}">${img(gallery[slide],p.name+' gallery image '+(slide+1),'gallery-photo')}<button class="gallery-arrow previous" data-action="gallery-prev" aria-label="Previous gallery image" ${slide===0?'disabled':''}>${arrow}</button><button class="gallery-arrow next" data-action="gallery-next" data-count="${gallery.length}" aria-label="Next gallery image" ${slide===gallery.length-1?'disabled':''}>${arrow}</button></div><div class="gallery-dots" role="tablist" aria-label="${esc(p.name)} gallery">${gallery.map((_,i)=>`<button role="tab" data-action="gallery-dot" data-index="${i}" class="${i===slide?'active':''}" aria-label="Gallery image ${i+1}" aria-selected="${i===slide}"></button>`).join('')}</div><p class="gallery-family-caption">${p.colors[d.color].image?esc(p.colors[d.color].name):esc(p.name)}</p></div><div class="apple-buy-config">${mac&&layoutGroups.length?configGroup(layoutGroups[0],ctx):''}${colorField}${['AirPods','AirTag','iPad'].includes(p.category)?`<button class="config-help-tile" data-action="engraving-open"><span><strong>${d.engraving?'Engraving: '+esc(d.engraving):'Add engraving'}</strong><small>Make it yours. Free engraving.</small></span><span class="circle-plus">+</span></button>`:''}${!accessory?helpTile('Compare models.','Find the one that’s right for you.','Compare '+p.name):''}${p.options.length>1?storage:''}${(!mac?layoutGroups:layoutGroups.slice(1)).map(g=>configGroup(g,ctx)).join('')}${!accessory?helpTile(p.optionName==='Storage'?'Not sure how much storage to get?':'Need a little help choosing?','Get a better understanding of what’s right for you.','Storage and configuration'):''}${compact?`${p.care?`<fieldset class="replica-group"><legend>AppleCare coverage. <span>Peace of mind in every plan.</span></legend><button class="apple-choice ${d.care?'selected':''}" data-action="care-select" data-value="yes"><strong>AppleCare+</strong><span>${money(p.care)}</span></button><button class="apple-choice ${!d.care?'selected':''}" data-action="care-select" data-value="no"><strong>No AppleCare coverage</strong></button></fieldset>`:''}<div class="accessory-buy-summary"><p>${simplePrice(price)}</p><p class="buy-delivery">${ctx.icon('truck')}<span>Delivery:<br><strong>${windowLabel(delivery)} — Free</strong></span></p><button class="button full-width" data-action="add-to-bag" data-id="${p.id}">Add to Bag</button><button class="text-button save-text" data-action="save" data-id="${p.id}">${ctx.icon('heart')} ${ctx.state.saved.includes(p.id)?'Saved for later':'Save for later'}</button></div>`:''}</div></div>${!compact?`<div class="buy-full-steps"><section class="buy-step"><h2>Apple Trade In. <span>Get credit toward your new ${p.category==='Mac'?'Mac':p.category==='iPhone'?'iPhone':p.name}.</span></h2><div class="buy-step-choices"><button class="apple-choice" data-action="product-help" data-topic="Apple Trade In"><span><strong>Add a trade-in</strong><small>Explore your trade-in options.</small></span><span>⊕</span></button><button class="apple-choice selected" data-action="product-help" data-topic="No trade-in"><strong>No trade-in</strong>${ctx.icon('check')}</button></div></section><section class="buy-step"><h2>Payment options. <span>Select the one that works for you.</span></h2><div class="buy-payment-choices">${[['buy','Buy',simplePrice(price),'Pay with your store wallet.'],['finance','Finance',money(Math.floor(price/24))+'/mo.','Pay over time at 0% APR.'],['lease','Lease with Apple Upgrade',money(Math.round(price*.029))+'/mo.','Easily upgrade at the end of your term.']].map(([value,title,amount,detail])=>`<button class="apple-choice payment-choice ${(d.payment||'buy')===value?'selected':''}" data-action="payment-choice" data-value="${value}"><strong>${title}</strong><span>${amount}</span><small>${detail}</small></button>`).join('')}</div>${d.payment&&d.payment!=='buy'?'<p class="small muted">The full product amount is reserved from your wallet at checkout.</p>':''}${helpTile('Not sure which payment option to choose?','Compare the options to find the one that’s right for you.','Payment options')}</section>${p.category==='iPhone'?`<section class="buy-step"><h2>Connectivity. <span>Choose a carrier.</span></h2><div class="carrier-choices">${['AT&T','T-Mobile','Verizon','Connect to any carrier later'].map((name,i)=>`<button class="apple-choice ${(d.carrier||0)===i?'selected':''}" data-action="carrier" data-index="${i}"><strong>${name}</strong><span>${simplePrice(price)}</span></button>`).join('')}</div>${helpTile('Is it easy to get connected?','Yes. Find the connection that works for you.','Connectivity')}</section>`:''}${p.care?`<section class="buy-step"><h2>AppleCare coverage. <span>Peace of mind in every plan.</span></h2><div class="buy-care-choices"><button class="apple-choice care-plan ${d.care?'selected':''}" data-action="care-select" data-value="yes"><strong>AppleCare+</strong><span>${money(p.care)}</span><small>Two years of coverage<br>Unlimited repairs for accidental damage<br>24/7 priority support</small></button><button class="apple-choice ${!d.care?'selected':''}" data-action="care-select" data-value="no"><strong>No AppleCare coverage</strong></button></div>${helpTile('How does AppleCare work?','Explore the features and coverage of AppleCare.','AppleCare')}</section>`:''}</div><section class="apple-final-summary"><div><h2>Your new ${p.name}.</h2><p>Just the way you want it.</p>${img(p.colors[d.color].image||p.thumb,p.name)}<button class="text-button save-text" data-action="save" data-id="${p.id}">${ctx.icon('heart')} ${ctx.state.saved.includes(p.id)?'Saved for later':'Save for later'}</button></div><div><h3>${p.name} ${esc(p.options[d.option][0])} ${esc(p.colors[d.color].name)}</h3><strong class="final-total">${simplePrice(price)}</strong><p class="small">One-time payment${d.care?' · AppleCare+ included':''}</p><p class="wallet-at-checkout">Your balance: <button data-action="wallet" class="text-button">${money(ctx.state.balance)}</button></p></div><div><p class="buy-delivery">${ctx.icon('truck')}<span>Delivers to your doorstep<br><strong>${windowLabel(delivery)} — Free</strong></span></p><p class="buy-delivery">${ctx.icon('bag')}<span>Pickup:<br><strong>Explore pickup options</strong></span></p><button class="button full-width" data-action="add-to-bag" data-id="${p.id}">Add to Bag</button></div></section>`:''}${accessory?`<section class="buy-faq accessory-information"><h2>Product Information</h2><details open><summary>Overview<span>+</span></summary><p>${esc(p.description||p.name)}</p></details><details><summary>What’s in the Box<span>+</span></summary><p>${p.name}</p></details></section>`:`<section class="whats-in-box"><h2>What’s in the Box</h2><div>${img(p.image,p.name)}<div class="box-usb-c"><span>◯</span><p>${p.category==='AirPods'?'Charging Case':p.category==='Watch'?'Magnetic Fast Charger to USB-C Cable':p.id==='mac-mini'||p.id==='mac-studio'||p.category==='Home'?'Power Cord':'USB-C Charge Cable'}</p></div></div><p>${p.name}</p></section>`}<section class="buy-faq"><h2>Frequently Asked Questions</h2>${[['How will I receive my order?','Your order appears in Orders with a delivery estimate and a shipment timeline. You can follow each update or skip ahead to the next milestone.'],['How can I pay for my new product?','Use your Store Wallet at checkout. You can manage your balance in Account.'],['Can I return or cancel my order?','You can cancel an order before it ships and the full balance will return to your wallet.'],['Where are my saved products?','Open the shopping bag menu and choose Your Saves. Your products and orders remain in this browser.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</section></div>`;
}

const menuData={Store:{heading:'Shop',large:[['Shop the Latest','#store'],['Mac','#category/Mac'],['iPad','#category/iPad'],['iPhone','#category/iPhone'],['Apple Watch','#category/Watch'],['Apple Vision Pro','#category/Vision'],['AirPods','#category/AirPods'],['Home','#category/Home'],['Accessories','#category/Accessories']]},Mac:{heading:'Explore Mac',large:[['Explore All Mac','#category/Mac'],['MacBook Air','#product/macbook-air'],['MacBook Pro','#product/mac'],['iMac','#product/imac'],['Mac mini','#product/mac-mini'],['Mac Studio','#product/mac-studio'],['MacBook Neo','#product/macbook-neo']]},iPad:{heading:'Explore iPad',large:[['Explore All iPad','#category/iPad'],['iPad Pro','#product/ipad-pro'],['iPad Air','#product/ipad-air'],['iPad mini','#product/ipad']]},iPhone:{heading:'Explore iPhone',large:[['Explore All iPhone','#category/iPhone'],['iPhone Duo','#product/duo'],['iPhone 18 Pro','#product/iphone'],['iPhone 17','#product/iphone-17']]},Watch:{heading:'Explore Watch',large:[['Explore All Apple Watch','#category/Watch'],['Apple Watch Series 12','#product/watch'],['Apple Watch Ultra 4','#product/apple-watch-ultra-4'],['Apple Watch Bands','#category/Accessories']]},Vision:{heading:'Explore Vision',large:[['Explore Apple Vision Pro','#product/vision']]},AirPods:{heading:'Explore AirPods',large:[['Explore All AirPods','#category/AirPods'],['AirPods 5','#product/airpods'],['AirPods Pro 3','#product/airpods-pro-3'],['AirPods Max 2','#product/airpods-max-2']]},Home:{heading:'Explore Home',large:[['Explore Home','#category/Home'],['Apple HomeView','#product/apple-homeview'],['HomePod mini 2','#product/homepod-mini-2'],['HomePod','#product/homepod']]},Entertainment:{heading:'Explore Entertainment',large:[['Explore Entertainment','#info/Entertainment'],['Apple One','#info/Apple%20One'],['Apple TV','#info/Apple%20TV'],['Apple Music','#info/Apple%20Music'],['Apple Arcade','#info/Apple%20Arcade']]},Accessories:{heading:'Shop Accessories',large:[['Shop All Accessories','#category/Accessories'],['Mac','#category/Mac'],['iPad','#category/iPad'],['iPhone','#category/iPhone'],['Apple Watch','#category/Watch'],['AirPods','#category/AirPods']]},Support:{heading:'Explore Support',large:[['Shopping Help','#info/Shopping%20Help'],['Order Status','#orders'],['Your Saves','#saved'],['Returns','#info/Returns']]}};
function menuMarkup(name,ctx){
  if(name==='mobile')return `<div class="mobile-apple-menu">${Object.keys(menuData).map(n=>`<button data-action="nav-submenu" data-name="${n}">${n}${arrow}</button>`).join('')}</div>`;
  if(name==='search')return `<div class="apple-search"><label>${ctx.icon('search')}<input id="apple-search-input" placeholder="Search apple.com" aria-label="Search apple.com" autocomplete="off"><button data-action="close-nav" aria-label="Close search">×</button></label><div class="apple-search-results"><span class="menu-column-label">Quick Links</span>${[['Find a Store','#info/Find%20a%20Store'],['Apple Upgrade','#info/Apple%20Upgrade'],['Apple Trade In','#info/Apple%20Trade%20In'],['Order Status','#orders'],['Your Saves','#saved']].map(([t,u])=>`<a href="${u}">→ <span>${t}</span></a>`).join('')}</div></div>`;
  if(name==='bag'){const count=ctx.state.bag.reduce((sum,i)=>sum+i.qty,0);return `<div class="apple-bag-flyout"><div class="bag-flyout-heading"><h2>${count?'Your Bag.':'Your Bag is empty.'}</h2>${count?`<a href="#bag" class="button">Review Bag (${count})</a>`:''}</div>${count?ctx.state.bag.slice(0,3).map(i=>{const p=CATALOG.find(p=>p.id===i.productId);return `<a class="bag-flyout-item" href="#bag">${img(p.colors[i.color].image||p.thumb,p.name)}<span><strong>${p.name}</strong><small>${p.options[i.option][0]} · ${p.colors[i.color].name}</small></span><span>${money(itemPrice(i)*i.qty)}</span></a>`;}).join(''):'<p class="bag-empty-save"><a href="#saved">See your saved items</a> when you’re ready to make them yours.</p>'}<span class="menu-column-label">My Profile</span><a href="#orders">${ctx.icon('box')} Orders</a><a href="#saved">${ctx.icon('heart')} Your Saves</a><button data-action="wallet">${ctx.icon('wallet')} Account <span>${money(ctx.state.balance)}</span></button></div>`;}
  const m=menuData[name]||menuData.Store;
  return `<div class="apple-menu-columns"><div class="menu-primary"><span class="menu-column-label">${m.heading}</span>${m.large.filter(([t,u])=>!u.startsWith('#product/')||CATALOG.some(p=>p.id===u.split('/')[1])).map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div><div><span class="menu-column-label">Quick Links</span><a href="#info/Find%20a%20Store">Find a Store</a><a href="#orders">Order Status</a><a href="#info/Apple%20Upgrade">Apple Upgrade</a><a href="#info/Apple%20Trade%20In">Apple Trade In</a><a href="#info/Financing">Financing</a><a href="#info/Personal%20Setup">Personal Setup</a></div><div><span class="menu-column-label">Shop Special Stores</span><a href="#info/Certified%20Refurbished">Certified Refurbished</a><a href="#info/Education">Education</a><a href="#info/Business">Business</a><a href="#info/Veterans%20and%20Military">Veterans and Military</a><a href="#info/Government">Government</a></div></div>`;
}
export function closeNav(){clearTimeout(navTimer);openMenu='';document.body.classList.remove('nav-is-open');const panel=document.querySelector('#apple-nav-panel');if(panel){panel.style.height='0px';panel.classList.remove('open');panel.setAttribute('aria-hidden','true');panel.inert=true;}document.querySelectorAll('[data-nav]').forEach(e=>e.setAttribute('aria-expanded','false'));}
function openNav(name){clearTimeout(navTimer);if(openMenu===name)return;openMenu=name;const panel=document.querySelector('#apple-nav-panel');panel.inert=false;panel.innerHTML=`<div class="apple-nav-inner">${menuMarkup(name,context())}</div>`;panel.style.height=Math.min(panel.firstElementChild.scrollHeight,window.innerHeight-44)+'px';panel.classList.add('open');panel.setAttribute('aria-hidden','false');document.body.classList.add('nav-is-open');document.querySelectorAll('[data-nav]').forEach(e=>e.setAttribute('aria-expanded',String(e.dataset.nav===name)));if(name==='search')requestAnimationFrame(()=>document.querySelector('#apple-search-input')?.focus());}
function directory(title,links){return `<div class="footer-directory-group"><h3>${title}</h3>${links.map(([t,u])=>`<a href="${u}">${t}</a>`).join('')}</div>`;}
export function renderChrome(ctx){
  const brand=document.querySelector('.brand').outerHTML;
  document.querySelector('.global-nav').innerHTML=brand+Object.keys(menuData).map(n=>`<a href="${menuData[n].large[0][1]}" class="nav-category" data-nav="${n}" aria-haspopup="true" aria-expanded="false">${n}</a>`).join('')+`<button class="icon-button" data-action="search-flyout" aria-label="Search apple.com">${ctx.icon('search')}</button><button id="bag-link" class="icon-button bag-link" data-action="bag-flyout" aria-label="Shopping Bag">${ctx.icon('bag')}<span class="bag-count" id="bag-count" hidden>0</span></button><button class="icon-button mobile-menu" data-action="mobile-nav" aria-label="Open menu">${ctx.icon('menu')}</button><span id="wallet-balance" class="visually-hidden" aria-hidden="true"></span>`;
  document.querySelector('.personal-bar')?.remove();
  document.querySelector('.global-header').insertAdjacentHTML('beforeend','<div id="apple-nav-panel" aria-hidden="true" inert></div>');
  document.querySelector('.global-header').insertAdjacentHTML('afterend','<div class="apple-nav-backdrop" data-action="close-nav" aria-hidden="true"></div>');
  document.querySelector('.site-footer').innerHTML=`<div class="apple-footer-inner"><div class="footer-breadcrumb"><a href="#store" aria-label="Apple Store">${brand.match(/<svg[\s\S]*?<\/svg>/)?.[0]||'●'}</a><span>›</span><span>Apple Store Online</span></div><div class="apple-footer-directory"><div>${directory('Shop and Learn',[['Store','#store'],...STORE_CATEGORIES.map(c=>[c.label,'#category/'+encodeURIComponent(c.name)])])}${directory('Apple Wallet',[['Wallet','#info/Wallet'],['Apple Pay','#info/Apple%20Pay']])}</div><div>${directory('Account',[['Your Store Account','#info/Account'],['Orders','#orders'],['Your Saves','#saved']])}${directory('Entertainment',[['Apple One','#info/Apple%20One'],['Apple TV','#info/Apple%20TV'],['Apple Music','#info/Apple%20Music'],['Apple Arcade','#info/Apple%20Arcade'],['Apple Fitness+','#info/Apple%20Fitness%2B']])}</div><div>${directory('Apple Store',[['Find a Store','#info/Find%20a%20Store'],['Genius Bar','#info/Genius%20Bar'],['Today at Apple','#info/Today%20at%20Apple'],['Apple Store App','#info/Apple%20Store%20App'],['Certified Refurbished','#info/Certified%20Refurbished'],['Apple Upgrade','#info/Apple%20Upgrade'],['Apple Trade In','#info/Apple%20Trade%20In'],['Financing','#info/Financing'],['Carrier Deals at Apple','#info/Carrier%20Deals'],['Order Status','#orders'],['Shopping Help','#info/Shopping%20Help']])}</div><div>${directory('For Business',[['Apple and Business','#info/Business'],['Shop for Business','#category/Mac']])}${directory('For Education',[['Apple and Education','#info/Education'],['Shop for College','#category/Mac']])}${directory('For Healthcare',[['Apple in Healthcare','#info/Healthcare'],['Health on Apple Watch','#category/Watch']])}${directory('For Government',[['Shop for Government','#info/Government'],['Shop for Veterans and Military','#info/Veterans']])}</div><div>${directory('Apple Values',[['Accessibility','#info/Accessibility'],['Education','#info/Education'],['Environment','#info/Environment'],['Privacy','#info/Privacy'],['Supply Chain','#info/Supply%20Chain']])}${directory('About Apple',[['About this Store','#info/About'],['Shopping Help','#info/Shopping%20Help'],['Your Account','#info/Account']])}</div></div><p class="footer-more-ways">More ways to shop: <a href="#store">Explore the Store</a> or browse <a href="#category/Accessories">accessories</a>.</p><div class="apple-footer-legal"><span>Apple trademarks and imagery © Apple Inc.</span><a href="#info/Privacy">Privacy</a><a href="#info/Shopping%20Help">Sales and Refunds</a><span>United States</span></div></div>`;
}

export function renderInfo(topic,ctx){const t=decodeURIComponent(topic||'Shopping Help');return `<div class="apple-info-page"><span class="new-label">Apple Store</span><h1>${esc(t)}</h1><p class="info-intro">A little help. A lot of possibilities.</p><div class="info-actions"><a class="button" href="#store">Shop the latest</a><button class="text-button" data-action="wallet">View your wallet ›</button><a class="text-button" href="#orders">Check your orders ›</a></div><div class="info-grid"><article><h2>Find the right product.</h2><p>Explore the lineup, choose your finish and configuration, and make it yours.</p><a href="#store">Explore the Store ›</a></article><article><h2>Your orders. All in one place.</h2><p>View your delivery estimate, follow each shipment update, or cancel before your order ships.</p><a href="#orders">View your orders ›</a></article><article><h2>A balance made for possibility.</h2><p>Manage your balance in Account. Add the amount you want and view your order history in one place.</p><button data-action="wallet" class="text-button">Open your wallet ›</button></article></div><div class="info-product-links">${STORE_CATEGORIES.map(c=>`<a href="#category/${encodeURIComponent(c.name)}">${img(c.image,c.label)}<strong>${c.label}</strong></a>`).join('')}</div></div>`;}

export function initPresentation(getContext){
  context=getContext;renderChrome(context());
  document.addEventListener('pointerover',e=>{const link=e.target.closest('[data-nav]');if(link&&matchMedia('(hover:hover)').matches){clearTimeout(navTimer);navTimer=setTimeout(()=>openNav(link.dataset.nav),80);}const card=e.target.closest('.store-card.has-preview');if(card&&!card.contains(e.relatedTarget)&&!prefersReduced()){const v=card.querySelector('video');v.currentTime=0;v.play().catch(()=>{});}});
  document.querySelector('.global-header').addEventListener('pointerleave',()=>{if(!['search','bag','mobile'].includes(openMenu))navTimer=setTimeout(closeNav,180);});
  document.addEventListener('pointerout',e=>{const card=e.target.closest('.store-card.has-preview');if(card&&!card.contains(e.relatedTarget))card.querySelector('video')?.pause();});
  document.addEventListener('focusin',e=>{const card=e.target.closest('.store-card.has-preview');if(card&&!prefersReduced())card.querySelector('video')?.play().catch(()=>{});});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();if(e.key==='ArrowDown'&&e.target.matches('[data-nav]')){e.preventDefault();openNav(e.target.dataset.nav);document.querySelector('#apple-nav-panel a')?.focus();}});
  document.addEventListener('click',e=>{
    const el=e.target.closest('[data-action]');const action=el?.dataset.action;
    if(e.target.closest('#apple-nav-panel a'))closeNav();
    if(['close-nav','search-flyout','bag-flyout','mobile-nav','nav-submenu'].includes(action)){e.preventDefault();if(action==='close-nav')closeNav();else{const target={ 'search-flyout':'search','bag-flyout':'bag','mobile-nav':'mobile'}[action]||el.dataset.name;openMenu===target?closeNav():openNav(target);}return;}
    if(action==='wallet')closeNav();
    if(action==='shelf-prev'||action==='shelf-next'){const row=el.closest('.apple-shelf').querySelector('.store-track');const first=row.firstElementChild;row.scrollBy({left:(action==='shelf-prev'?-1:1)*((first?.getBoundingClientRect().width||400)+20),behavior:prefersReduced()?'instant':'smooth'});}
    if(action==='preview'){e.preventDefault();e.stopPropagation();const v=el.closest('.store-card').querySelector('video');v.currentTime=0;v.play().catch(()=>{});}
    if(action==='shopping-guide'){context().modal('Find your next favorite.',`<div class="specialist-guide"><p>Let’s find the right product for you.</p>${STORE_CATEGORIES.slice(0,7).map(c=>`<a href="#category/${encodeURIComponent(c.name)}" data-action="close-link">${img(c.image,c.label)}<strong>${c.label}</strong>${arrow}</a>`).join('')}</div>`);}
    if(action==='store-location'){context().modal('Your Apple Store.',`<div class="location-preview">${context().icon('bag')}<h3>A little closer to yours.</h3><p>Find the products you love.</p><p>Browse the latest lineup and choose the right configuration for you.</p><a href="#store" data-action="close-link" class="button">Continue shopping</a></div>`);}
    if(action==='product-help'){const topic=el.dataset.topic;context().modal(topic,`<div class="product-help-content"><h3>${esc(topic)}.</h3><p>${topic.includes('storage')||topic.includes('Storage')?'More storage gives you more room for photos, videos, apps, and everything you love. Choose a capacity that fits the way you use your device.':topic.includes('Trade')?'Choose No trade-in to keep your current device and continue with your order.':topic.includes('Care')?'Your selected plan appears with your product in your order details.':topic.includes('No trade')?'Your new product is yours to enjoy, with no trade-in selected.':topic.includes('Payment')||topic.includes('deals')?'Compare your options, then complete checkout with your Store Wallet.':'Explore the options and choose the configuration that feels right for you.'}</p><button class="button" data-action="close-modal">Continue</button></div>`);}
  });
  document.addEventListener('input',e=>{if(e.target.id!=='apple-search-input')return;const q=e.target.value.trim().toLowerCase();const list=CATALOG.filter(p=>(p.name+' '+p.category).toLowerCase().includes(q));document.querySelector('.apple-search-results').innerHTML=`<span class="menu-column-label">${q?'Suggested Products':'Explore Products'}</span>${list.slice(0,8).map(p=>`<a href="#product/${p.id}">→ <span>${p.name}</span><small>${simplePrice(p.price)}</small></a>`).join('')||'<p>No matching products. Try iPhone, Mac, or AirPods.</p>'}`;});
  window.addEventListener('hashchange',closeNav);
  let drag;
  document.addEventListener('pointerdown',e=>{const track=e.target.closest('.store-track');if(!track||e.pointerType!=='mouse'||e.button!==0||e.target.closest('button'))return;drag={track,x:e.clientX,y:e.clientY,left:track.scrollLeft,moved:false};});
  document.addEventListener('dragstart',e=>{if(e.target.closest('.store-track'))e.preventDefault();});
  document.addEventListener('pointercancel',()=>{drag=null;});
  document.addEventListener('pointermove',e=>{if(!drag)return;if(Math.abs(e.clientX-drag.x)>7&&Math.abs(e.clientX-drag.x)>Math.abs(e.clientY-drag.y)){drag.moved=true;drag.track.classList.add('is-dragging');drag.track.scrollLeft=drag.left-(e.clientX-drag.x);e.preventDefault();}});
  document.addEventListener('pointerup',()=>{if(!drag)return;const d=drag;d.track.classList.remove('is-dragging');if(d.moved){const stop=e=>{e.preventDefault();e.stopPropagation();};d.track.addEventListener('click',stop,{capture:true,once:true});setTimeout(()=>d.track.removeEventListener('click',stop,true),100);}drag=null;});
}
export function refreshPresentation(){
  mediaObserver?.disconnect();
  document.querySelectorAll('.store-track').forEach(track=>{const controls=track.closest('.apple-shelf').querySelector('.shelf-controls');if(!controls)return;const update=()=>{controls.children[0].disabled=track.scrollLeft<5;controls.children[1].disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-5;};track.addEventListener('scroll',update,{passive:true});update();});
  if(matchMedia('(hover:none)').matches&&!prefersReduced()){mediaObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)entry.target.play().catch(()=>{});else entry.target.pause();}),{threshold:.6});document.querySelectorAll('.store-preview').forEach(v=>mediaObserver.observe(v));}
}
